# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Timekeeping handoff round trip of the monolith checkpoint file" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:round_trip_service_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => round_trip_service_token
    ) { example.run }
  end

  after { ApplicationRecord.connection.execute("TRUNCATE invoice_operations") }

  # Issue: "Populated audits, idempotency receipts and operation receipts round-trip between the two stores unchanged"
  # The rows of one company must come back under that company and no other.
  it "returns every company's audits, receipts and operation receipts from the monolith checkpoint file under that same company after load and export" do
    body = Rails.root.join("../spec/fixtures/files/timekeeping_handoff/monolith_checkpoint.json").read
    source = Timekeeping::Handoff::Checkpoint.from_json(body)
    headers = { "Authorization" => "Bearer #{round_trip_service_token}", "Content-Type" => "application/json" }
    Timekeeping::Admission.fence!

    put "/internal/v1/handoff/checkpoint", params: body, headers: headers
    expect(response.status).to eq(200)
    get "/internal/v1/handoff/checkpoint", headers: headers
    expect(response.status).to eq(200)
    exported = Timekeeping::Handoff::Checkpoint.from_json(response.body)

    by_company = ->(rows) { rows.group_by { |row| row["company_id"] }.transform_values { |list| list.sort_by(&:to_s) } }
    %w[entry_audits idempotency_records invoice_operations].each do |table|
      expect(by_company.call(source.rows.fetch(table)).keys.size).to be >= 2, "#{table} fixture covers two companies"
      expect(by_company.call(exported.rows.fetch(table))).to eq(by_company.call(source.rows.fetch(table))), table
    end
    expect(exported.digest).to eq(source.digest)
  end
end
